// js/shell-main.js — Encrypted UI shell for index.html
(function (root) {
  const ENCRYPTED_SHELL = "";
  root.__MAIN_SHELL_ENC__ = ENCRYPTED_SHELL;

  function hydrate() {
    if (!document || !document.body) return false;
    if (document.body.getAttribute("data-shell-main-mounted") === "1") return true;
    if (!root.ContentShield || typeof root.ContentShield.decodePayload !== "function") {
      return false;
    }
    const payload = root.ContentShield.decodePayload(ENCRYPTED_SHELL);
    if (!payload || typeof payload.html !== "string") return false;
    if (payload.title) {
      document.title = payload.title;
    }
    document.body.insertAdjacentHTML("afterbegin", payload.html);
    document.body.setAttribute("data-shell-main-mounted", "1");
    return true;
  }

  root.hydrateMainShell = hydrate;
})(typeof window !== "undefined" ? window : globalThis);
